'use strict';
(() => {
const SVG={
 'layout-dashboard':'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
 'package':'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 7 9 5 9-5M3 7v10l9 5 9-5V7M12 12v10"/>',
 'wallet':'<path d="M20 7V5a2 2 0 0 0-2-2H5a3 3 0 0 0-3 3v12a3 3 0 0 0 3 3h15a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2H5a3 3 0 0 1-3-3"/><path d="M18 15h.01"/>',
 'users':'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>',
 'receipt':'<path d="M4 3v18l4-2 4 2 4-2 4 2V3l-4 2-4-2-4 2-4-2Z"/><path d="M8 9h8M8 13h6"/>',
 'chart':'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16V4"/>',
 'settings':'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.86 2.86-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 1.55V21H10v-.05A1.7 1.7 0 0 0 9 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06L4.2 16.94l.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.55-1H3v-4h.05A1.7 1.7 0 0 0 4.6 9a1.7 1.7 0 0 0-.34-1.88L4.2 7.06 7.06 4.2l.06.06A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.55V3h4v.05A1.7 1.7 0 0 0 15 4.6a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.86 2.86-.06.06A1.7 1.7 0 0 0 19.4 9a1.7 1.7 0 0 0 1.55 1H21v4h-.05A1.7 1.7 0 0 0 19.4 15Z"/>',
 'shield':'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
 'log-out':'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',
 'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
 'download':'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 'upload':'<path d="M12 16V4m-4 4 4-4 4 4M4 17v4h16v-4"/>',
 'plus':'<path d="M12 5v14M5 12h14"/>',
 'search':'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
 'chevron-right':'<path d="m9 18 6-6-6-6"/>',
 'x':'<path d="M18 6 6 18M6 6l12 12"/>',
 'truck':'<path d="M3 6h12v11H3zM15 10h4l3 4v3h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
 'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 'coins':'<circle cx="9" cy="9" r="6"/><path d="M14 9c4 0 7 3 7 6s-3 6-7 6c-2 0-4-1-5-2"/>',
 'arrow-up-right':'<path d="M7 17 17 7M8 7h9v9"/>',
 'check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
 'alert-circle':'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 4h.01"/>',
 'calendar':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
 'file-text':'<path d="M6 2h9l5 5v15H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2ZM14 2v6h6M8 13h8M8 17h8"/>',
 'printer':'<path d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6zM18 12h.01"/>',
 'message-circle':'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9H13a8.5 8.5 0 0 1 8 8v.5Z"/>',
 'edit':'<path d="m16 4 4 4M4 20l4.5-.8L20 7.7a2.8 2.8 0 0 0-4-4L4.5 15.2 4 20Z"/>',
 'trash':'<path d="M4 7h16M10 4h4m-8 3 1 14h10l1-14M10 11v6M14 11v6"/>',
 'building':'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 7h1M14 7h1M9 12h1M14 12h1M9 17h6"/>',
 'filter':'<path d="M4 7h16M7 12h10M10 17h4"/>',
 'archive':'<rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v12h14V9M10 14h4"/>',
 'more':'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'
};
const ico=(name)=>`<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true">${SVG[name]||SVG.package}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupee=x=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(x)||0);
const fmt=x=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(Number(x)||0);
const shortDate=s=>{if(!s)return '—';const d=new Date(`${s}T12:00:00Z`);return Number.isNaN(d.getTime())?String(s):new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(d);};
const dateShift=(s,n)=>{const d=new Date(`${s}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const diffDays=(a,b)=>Math.round((new Date(`${a}T12:00:00Z`)-new Date(`${b}T12:00:00Z`))/86400000);
const titleCase=s=>s==='In Transit'?'In transit':s;
const paymentStatus=b=>{if(b.delivery_status==='Cancelled')return ['Cancelled','cancelled'];if(Number(b.balance)<=0)return ['Paid','paid'];if(b.due_date<S.today)return ['Overdue','overdue'];if(Number(b.paid)>0)return ['Partial','partial'];return ['Pending','pending'];};
const badge=(label,cls)=>`<span class="badge ${esc(cls)}"><span class="dot"></span>${esc(label)}</span>`;
const pbadge=b=>{const [l,c]=paymentStatus(b);return badge(l,c);};
const deliveryBadge=s=>badge(s,s==='Delivered'?'delivered':s==='In Transit'?'intransit':s==='Cancelled'?'cancelled':'booked');
const empty=(icon,title,description,btn='')=>`<div class="empty"><div class="empty-icon">${ico(icon)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${btn}</div>`;
const metric=(label,value,icon,foot,tone='')=>`<div class="metric-card"><div class="metric-top"><span class="metric-title">${esc(label)}</span><span class="metric-icon ${tone}">${ico(icon)}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-foot">${foot}</div></div>`;
const head=(name,description,buttons='')=>`<div class="page-head"><div><h1>${esc(name)}</h1><p>${esc(description)}</p></div><div class="page-actions">${buttons}</div></div>`;
const card=(title,description,content,more='')=>`<div class="card card-pad"><div class="card-titlebar"><div><h2 class="section-title">${esc(title)}</h2>${description?`<p class="subtext">${esc(description)}</p>`:''}</div>${more}</div>${content}</div>`;
const field=(label,name,value='',opts={})=>{const type=opts.type||'text', required=opts.required?'required':'', min=opts.min!==undefined?`min="${opts.min}"`:'',step=opts.step!==undefined?`step="${opts.step}"`:'',help=opts.hint?`<small class="hint">${esc(opts.hint)}</small>`:'',placeholder=opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:'';
 let control;if(opts.options){control=`<select name="${name}" ${required}>${opts.options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`;}
 else if(type==='textarea'){control=`<textarea name="${name}" ${required} ${placeholder}>${esc(value)}</textarea>`;}
 else control=`<input name="${name}" type="${type}" value="${esc(value)}" ${required} ${min} ${step} ${placeholder} ${opts.readonly?'readonly':''} />`;
 return `<label class="field ${opts.span?'span-'+opts.span:''}"><span>${esc(label)}${opts.required?' *':''}</span>${control}${help}</label>`;};
const subTitle=t=>`<div class="form-section-title span-2">${esc(t)}</div>`;
const forms=(name,fields,submit='Save',note='')=>`<form id="${name}"><div class="form-grid">${fields}</div>${note?`<p class="form-aside">${note}</p>`:''}<p class="form-error-inline" id="modal-error" hidden></p><div class="modal-foot" style="margin:22px -27px -28px"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${ico('check-circle')}${esc(submit)}</button></div></form>`;
const S={page:'dashboard',today:new Date().toISOString().slice(0,10),user:null,settings:{},customers:[],bookings:[],payments:[],expenses:[],report:null,dashboard:null,filters:{bookings:{q:'',payment:'all',status:'all'},payments:{q:''},customers:{q:''},expenses:{q:''}},reportFilter:{from:'',to:''},modal:null,installEvent:null};
const el=id=>document.getElementById(id);
async function api(url,options={}){const config={credentials:'same-origin',...options};if(options.body&&typeof options.body!=='string'){config.body=JSON.stringify(options.body);config.headers={'Content-Type':'application/json',...(options.headers||{})};}let r;try{r=await fetch(url,config);}catch{throw new Error('Cannot connect to the server. Check your PC/server connection and try again.');}const json=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&S.user)showAuth(false);throw new Error(json.error||`Request failed (${r.status})`);}return json;}
function toast(message,type='info'){const t=document.createElement('div');t.className='toast '+type;t.textContent=message;el('toast-root').appendChild(t);setTimeout(()=>t.remove(),4200);}
function fillIcons(){document.querySelectorAll('[data-ico]').forEach(n=>{n.innerHTML=ico(n.dataset.ico);});}
function showAuth(setup){el('auth-screen').hidden=false;el('app').hidden=true;el('auth-description').textContent=setup?'Create your administrator account to start managing New Raja Transport.':'Sign in to manage bookings, payments and customer accounts.';el('auth-submit').innerHTML=setup?'Create administrator account →':'Sign in →';el('auth-form').dataset.mode=setup?'setup':'login';el('auth-form').reset();el('auth-error').hidden=true;S.user=null;}
async function startup(){fillIcons();el('footer-year').textContent=new Date().getFullYear();try{const status=await api('/api/status');if(status.setup_required){showAuth(true);return;}const me=await api('/api/me');S.user=me.user;S.settings=me.settings;S.today=me.today;showApp();}catch(e){if(e.message==='Please log in'){showAuth(false);}else{showAuth(false);toast(e.message,'error');}}}
async function signIn(ev){ev.preventDefault();const f=ev.currentTarget;const mode=f.dataset.mode||'login';const data=Object.fromEntries(new FormData(f));const err=el('auth-error');err.hidden=true;const btn=el('auth-submit');btn.disabled=true;try{const result=await api('/api/'+mode,{method:'POST',body:data});S.user=result.user;const me=await api('/api/me');S.settings=me.settings;S.today=me.today;showApp();toast(mode==='setup'?'Account created. Welcome!':'Welcome back!','success');}catch(e){err.textContent=e.message;err.hidden=false;}finally{btn.disabled=false;}}
function showApp(){el('auth-screen').hidden=true;el('app').hidden=false;el('sidebar-username').textContent=S.user.username;el('today-label').textContent=shortDate(S.today);go('dashboard');}
function mobileClose(){el('sidebar').classList.remove('open');el('mobile-backdrop').classList.remove('active');}
async function go(page){S.page=page;mobileClose();document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('is-active',b.dataset.nav===page));const labels={dashboard:'Dashboard',bookings:'Bookings / LR',payments:'Payments',customers:'Customers',expenses:'Expenses',reports:'Reports',settings:'Settings & Backup'};el('crumb-title').textContent=labels[page]||page;el('main-content').innerHTML='<div class="loading-page"><div class="spinner"></div><p>Loading records...</p></div>';
 try{await load(page);if(S.page!==page)return;render();window.scrollTo({top:0,behavior:'instant'});}catch(e){el('main-content').innerHTML=empty('alert-circle','Unable to load this page',e.message,`<button class="btn btn-outline" data-action="reload">Try again</button>`);toast(e.message,'error');}}
async function load(page){if(page==='dashboard'){S.dashboard=await api('/api/dashboard');}if(page==='bookings'){S.bookings=await api('/api/bookings?'+new URLSearchParams(S.filters.bookings));}if(page==='payments'){S.payments=await api('/api/payments?'+new URLSearchParams(S.filters.payments));}if(page==='customers'){S.customers=await api('/api/customers?'+new URLSearchParams(S.filters.customers));}if(page==='expenses'){S.expenses=await api('/api/expenses?'+new URLSearchParams(S.filters.expenses));}if(page==='reports'){if(!S.reportFilter.from){S.reportFilter.from=`${S.today.slice(0,7)}-01`;S.reportFilter.to=S.today;}S.report=await api('/api/reports?'+new URLSearchParams(S.reportFilter));}}
function render(){let html='';switch(S.page){case'dashboard':html=dashboard();break;case'bookings':html=bookingsPage();break;case'payments':html=paymentsPage();break;case'customers':html=customersPage();break;case'expenses':html=expensesPage();break;case'reports':html=reportsPage();break;case'settings':html=settingsPage();break;}el('main-content').innerHTML=html;}
function dashboard(){const d=S.dashboard,max=Math.max(1,...d.months.flatMap(m=>[m.received,m.freight]));const monthBars=d.months.map(m=>`<div class="bar-cluster" title="${esc(m.month)} — Freight ${rupee(m.freight)}, Received ${rupee(m.received)}"><div class="bar-pair"><div class="bar freight" style="height:${Math.max(2,m.freight/max*100)}%"></div><div class="bar collection" style="height:${Math.max(2,m.received/max*100)}%"></div></div><span class="bar-month">${new Date(m.month+'-01T12:00:00Z').toLocaleDateString('en-IN',{month:'short',timeZone:'UTC'})}</span></div>`).join('');
 const recent=d.recent_payments.length?`<div class="activity-list">${d.recent_payments.map(p=>`<div class="activity-item"><span class="activity-icon">${ico('arrow-up-right')}</span><div class="activity-copy"><strong>${esc(p.payer_name)}</strong><small>${esc(p.lr_no)} · ${shortDate(p.payment_date)} · ${esc(p.method)}</small></div><span class="activity-money">+ ${rupee(p.amount)}</span></div>`).join('')}</div>`:empty('wallet','No payments yet','Payments recorded against bookings will appear here.');
 const overdue=d.top_overdue.length?`<div class="overdue-list">${d.top_overdue.map(b=>`<div class="overdue-item"><div class="number-box">${ico('clock')}</div><div class="item-main"><strong>${esc(b.customer_name)}</strong><small>${esc(b.lr_no)} · Due ${shortDate(b.due_date)}</small></div><div class="item-end"><strong>${rupee(b.balance)}</strong><small>${diffDays(S.today,b.due_date)} days late</small></div><button class="icon-btn" aria-label="View ${esc(b.lr_no)}" data-booking="${b.id}">${ico('chevron-right')}</button></div>`).join('')}</div>`:empty('check-circle','No overdue payments','Great! No transport bookings currently have overdue balances.');
 const noData=Number(d.booking_count)===0?`<div class="welcome-banner"><div><strong>Welcome to New Raja Transport</strong><p>Add your first customer and booking, or explore with clearly labelled sample records.</p></div><button class="btn" data-action="demo">Load demo data</button></div>`:'';
 return `${head('Good to see you 👋',`Here’s how New Raja Transport is performing as of ${shortDate(d.today)}.`)}${noData}<div class="metric-grid">${metric('Total freight billed',rupee(d.total_freight),'truck',`${fmt(d.booking_count)} total bookings`)}${metric('Payments received',rupee(d.received),'wallet',`${rupee(d.this_month_received)} this month`,'green-bg')}${metric('Outstanding balance',rupee(d.outstanding),'coins','Total unpaid freight','orange-bg')}${metric('Overdue payments',rupee(d.overdue),'clock',`${fmt(d.overdue_count)} overdue bookings`,'red-bg')}</div><div class="page-grid">${card('Freight vs collections','Last 6 months',`<div class="chart-wrap">${monthBars}</div><div class="chart-legend"><span><i class="legend leg-billed"></i>Freight booked</span><span><i class="legend leg-paid"></i>Payments collected</span></div>`)}${card('Quick actions','Everything you need, one click away',`<div class="quick-grid"><button class="quick-action" data-action="new-booking">${ico('plus')}New booking</button><button class="quick-action" data-action="new-payment">${ico('wallet')}Record payment</button><button class="quick-action" data-action="new-customer">${ico('users')}Add customer</button><button class="quick-action" data-action="new-expense">${ico('receipt')}Add expense</button><button class="quick-action" data-nav="reports">${ico('chart')}View reports</button><button class="quick-action" data-nav="bookings">${ico('package')}All bookings</button></div>`)}</div><div class="page-grid">${card('Overdue follow-ups','Oldest pending invoices first',overdue,'<button class="card-link" data-action="open-overdue">View all overdue →</button>')}${card('Recently received','Latest payments collected',recent,'<button class="card-link" data-nav="payments">All payments →</button>')}</div>`;
}
function bookingRows(rows){return rows.map(b=>`<tr class="clickable" data-booking="${b.id}"><td><strong class="mono">${esc(b.lr_no)}</strong><span class="minor">${shortDate(b.booking_date)}</span></td><td><strong>${esc(b.customer_name)}</strong><span class="minor">${esc(b.sender_name)} → ${esc(b.receiver_name)}</span></td><td><strong>${esc(b.from_city)}</strong><span class="minor">→ ${esc(b.to_city)}</span></td><td>${rupee(b.freight)}</td><td class="amount-green">${rupee(b.paid)}</td><td class="${b.balance>0?'amount-red':'amount-green'}">${rupee(b.balance)}</td><td><span>${shortDate(b.due_date)}</span>${b.balance>0&&b.due_date<S.today?`<span class="minor red">${diffDays(S.today,b.due_date)} days late</span>`:''}</td><td>${pbadge(b)}</td><td><button class="btn btn-xs btn-outline" data-booking="${b.id}">Details ${ico('chevron-right')}</button></td></tr>`).join('');}
function bookingsPage(){const f=S.filters.bookings;return `${head('Freight bookings','All consignments, freight amounts and collections in one place.',`<button class="btn btn-primary" data-action="new-booking">${ico('plus')} Add booking</button>`)}<div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${ico('search')}<input data-filter="bookings.q" value="${esc(f.q)}" placeholder="Search LR, customer, route..." /></label><select class="filter-select" data-filter="bookings.payment"><option value="all">All payments</option>${[['pending','Pending balance'],['overdue','Overdue only'],['due_soon','Due in 7 days'],['paid','Fully paid']].map(([v,t])=>`<option value="${v}" ${f.payment===v?'selected':''}>${t}</option>`).join('')}</select><select class="filter-select" data-filter="bookings.status">${[['all','All delivery status'],['Booked','Booked'],['In Transit','In transit'],['Delivered','Delivered'],['Cancelled','Cancelled']].map(([v,t])=>`<option value="${v}" ${f.status===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="toolbar-right"><button class="btn btn-outline btn-sm" data-action="export-bookings">${ico('download')} Export CSV</button></div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>LR number / date</th><th>Customer / parties</th><th>Route</th><th>Freight</th><th>Received</th><th>Balance</th><th>Due date</th><th>Payment</th><th></th></tr></thead><tbody>${S.bookings.length?bookingRows(S.bookings):`<tr><td colspan="9">${empty('package','No bookings found','Create a booking or change the filters to see consignment records.',`<button class="btn btn-primary btn-sm" data-action="new-booking">New booking</button>`)}</td></tr>`}</tbody></table></div><div class="table-bottom"><span>Showing ${fmt(S.bookings.length)} bookings</span><span>Click a row to view details and payments</span></div></div>`;}
function paymentsPage(){const sum=S.payments.reduce((a,p)=>a+Number(p.amount),0);return `${head('Payment register','Know who paid, when they paid, and how much was received.',`<button class="btn btn-primary" data-action="new-payment">${ico('plus')} Record payment</button>`)}<div class="metric-grid" style="margin-bottom:19px;grid-template-columns:repeat(2,minmax(0,1fr));max-width:560px">${metric('Payments in this view',rupee(sum),'wallet',`${S.payments.length} transactions`,'green-bg')}${metric('Total transactions',fmt(S.payments.length),'file-text','Search by LR or payer')}</div><div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${ico('search')}<input data-filter="payments.q" value="${esc(S.filters.payments.q)}" placeholder="Search payer, LR, reference..." /></label></div><div class="toolbar-right"><button class="btn btn-outline btn-sm" data-action="export-payments">${ico('download')} Export CSV</button></div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Receipt</th><th>Payment date</th><th>LR number</th><th>Customer</th><th>Paid by</th><th>Method / reference</th><th>Amount</th><th>Actions</th></tr></thead><tbody>${S.payments.length?S.payments.map(p=>`<tr><td><strong>#${String(p.id).padStart(5,'0')}</strong></td><td>${shortDate(p.payment_date)}</td><td><button class="card-link mono" data-booking="${p.booking_id}">${esc(p.lr_no)}</button></td><td>${esc(p.customer_name)}</td><td><strong>${esc(p.payer_name)}</strong></td><td>${badge(p.method,'booked')}<span class="minor">${esc(p.reference||'')}</span></td><td class="amount-green">+ ${rupee(p.amount)}</td><td><div class="row-actions"><button title="Print receipt" data-action="print-payment" data-id="${p.id}">${ico('printer')}</button><button title="Edit payment" data-action="edit-payment" data-id="${p.id}">${ico('edit')}</button><button title="Delete payment" data-action="delete-payment" data-id="${p.id}">${ico('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="8">${empty('wallet','No payment records','Record received cash, UPI or bank transfers against a booking.',`<button class="btn btn-primary btn-sm" data-action="new-payment">Record payment</button>`)}</td></tr>`}</tbody></table></div><div class="table-bottom"><span>${S.payments.length} payment records</span><span>Payment receipts can be printed individually</span></div></div>`;}
function customersPage(){return `${head('Customer accounts','Manage billing parties and view each customer’s outstanding balance.',`<button class="btn btn-primary" data-action="new-customer">${ico('plus')} Add customer</button>`)}<div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${ico('search')}<input data-filter="customers.q" value="${esc(S.filters.customers.q)}" placeholder="Search customer or phone..." /></label></div><div class="toolbar-right"><button class="btn btn-outline btn-sm" data-action="export-customers">${ico('download')} Export CSV</button></div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Customer / company</th><th>Phone / WhatsApp</th><th>GSTIN</th><th>Bookings</th><th>Total freight</th><th>Outstanding</th><th>Actions</th></tr></thead><tbody>${S.customers.length?S.customers.map(c=>`<tr><td><div class="customer-name"><span class="customer-avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(c.name)}</strong><span class="minor">${esc(c.address||'No address')}</span></div></div></td><td>${esc(c.phone||'—')}<span class="minor">${c.whatsapp?'WhatsApp: '+esc(c.whatsapp):''}</span></td><td class="mono">${esc(c.gstin||'—')}</td><td>${c.booking_count}</td><td class="amount-dark">${rupee(c.total_freight)}</td><td class="${c.balance?'amount-red':'amount-green'}">${rupee(c.balance)}</td><td><div class="row-actions"><button title="Customer ledger" data-customer="${c.id}">${ico('file-text')}</button><button title="Edit customer" data-action="edit-customer" data-id="${c.id}">${ico('edit')}</button><button title="Delete customer" data-action="delete-customer" data-id="${c.id}">${ico('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="7">${empty('users','No customers yet','Add the transport companies or parties you bill.',`<button class="btn btn-primary btn-sm" data-action="new-customer">Add customer</button>`)}</td></tr>`}</tbody></table></div><div class="table-bottom"><span>${S.customers.length} customer accounts</span><span>Use the ledger icon to see all bookings</span></div></div>`;}
function expensesPage(){const total=S.expenses.reduce((a,e)=>a+Number(e.amount),0);return `${head('Business expenses','Track diesel, tolls, repairs, driver advances and operating costs.',`<button class="btn btn-primary" data-action="new-expense">${ico('plus')} Add expense</button>`)}<div class="metric-grid" style="margin-bottom:18px;grid-template-columns:repeat(2,minmax(0,1fr));max-width:560px">${metric('Recorded expenses',rupee(total),'receipt',`${S.expenses.length} expense entries`,'orange-bg')}${metric('Expense entries',fmt(S.expenses.length),'file-text','Keep every cost documented')}</div><div class="toolbar"><div class="toolbar-left"><label class="search-wrap">${ico('search')}<input data-filter="expenses.q" value="${esc(S.filters.expenses.q)}" placeholder="Search category, vehicle, paid to..." /></label></div><div class="toolbar-right"><button class="btn btn-outline btn-sm" data-action="export-expenses">${ico('download')} Export CSV</button></div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Category</th><th>Paid to</th><th>Vehicle</th><th>Method</th><th>Amount</th><th>Actions</th></tr></thead><tbody>${S.expenses.length?S.expenses.map(x=>`<tr><td>${shortDate(x.expense_date)}</td><td><strong>${esc(x.category)}</strong><span class="minor">${esc(x.notes||'')}</span></td><td>${esc(x.paid_to||'—')}</td><td>${esc(x.vehicle_no||'—')}</td><td>${esc(x.payment_method)}</td><td class="amount-red">${rupee(x.amount)}</td><td><div class="row-actions"><button title="Edit expense" data-action="edit-expense" data-id="${x.id}">${ico('edit')}</button><button title="Delete expense" data-action="delete-expense" data-id="${x.id}">${ico('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="7">${empty('receipt','No expenses recorded','Keep track of diesel, tolls and operational expenses.',`<button class="btn btn-primary btn-sm" data-action="new-expense">Add expense</button>`)}</td></tr>`}</tbody></table></div><div class="table-bottom"><span>${S.expenses.length} expense records</span><span>Expenses are included in the cash flow report</span></div></div>`;}
function reportsPage(){const r=S.report,agingOrder=['Not due','1–7 days','8–30 days','31–60 days','60+ days'];const max=Math.max(1,...r.aging.map(x=>x.amount));const aging=agingOrder.map(n=>{const a=r.aging.find(x=>x.bucket===n)||{amount:0,count:0};return `<div class="age-row"><span class="age-name">${esc(n)}</span><div class="age-track"><div class="age-fill" style="width:${a.amount/max*100}%"></div></div><span class="age-amount">${rupee(a.amount)}</span></div>`;}).join('');
 return `${head('Business reports','Understand collections, spending, and who still owes money.',`<button class="btn btn-outline" data-action="backup">${ico('download')} Full backup</button>`)}<div class="toolbar"><div class="toolbar-left"><span class="small strong muted">Report period</span><input class="date-input" type="date" id="report-from" value="${esc(r.from)}"/><span class="small muted">to</span><input class="date-input" type="date" id="report-to" value="${esc(r.to)}"/><button class="btn btn-primary btn-sm" data-action="apply-report">Apply</button></div><div class="toolbar-right"><button class="btn btn-outline btn-sm" data-action="export-bookings">${ico('download')} Bookings CSV</button><button class="btn btn-outline btn-sm" data-action="export-payments">${ico('download')} Payments CSV</button></div></div><div class="report-main">${metric('Freight billed',rupee(r.billed),'truck',`${r.bookings} bookings in period`)}${metric('Payments collected',rupee(r.collections),'wallet',`${r.payment_count} collections`,'green-bg')}${metric('Expenses paid',rupee(r.expenses),'receipt','Recorded in period','orange-bg')}${metric('Net cash flow',rupee(r.cash_flow),'chart','Collections − expenses',r.cash_flow>=0?'green-bg':'red-bg')}</div><div class="page-grid equal">${card('Outstanding aging','Unpaid freight grouped by number of days past due',aging)}${card('Collections by method','Payments received in selected period',r.payment_methods.length?r.payment_methods.map(x=>`<div class="split-stat"><span>${esc(x.method)} <span class="muted">(${x.count})</span></span><strong>${rupee(x.amount)}</strong></div>`).join(''):empty('wallet','No collections','No payments recorded in this period.'))}</div><div class="card card-pad" style="margin-top:18px"><div class="card-titlebar"><div><h2 class="section-title">Customer outstanding ledger</h2><p class="subtext">All-time unpaid balances by billed customer</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Bookings</th><th>Total freight</th><th>Outstanding</th><th></th></tr></thead><tbody>${r.customers.length?r.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.phone||'—')}</td><td>${c.booking_count}</td><td>${rupee(c.freight)}</td><td class="amount-red">${rupee(c.outstanding)}</td><td><button class="btn btn-outline btn-xs" data-customer="${c.id}">View ledger</button></td></tr>`).join(''):`<tr><td colspan="6">${empty('check-circle','No outstanding balances','Nothing is pending for these customers.')}</td></tr>`}</tbody></table></div></div>`;}
function settingsPage(){const s=S.settings;return `${head('Settings & backup','Configure your business profile and protect your records.') }<div class="settings-grid"><div class="card card-pad"><div class="card-titlebar"><div><h2 class="section-title">Company profile</h2><p class="subtext">Used on printed invoices and payment receipts</p></div></div><form id="settings-form"><div class="form-grid">${field('Business name','company_name',s.company_name,{span:2,required:true})}${field('Contact phone','phone',s.phone)}${field('GSTIN (optional)','gstin',s.gstin)}${field('Office address','address',s.address,{span:2,type:'textarea'})}${field('Default payment terms (days)','default_due_days',s.default_due_days,{type:'number',min:0})}${field('Business tagline','tagline',s.tagline)}<div class="span-2" style="margin-top:8px"><button class="btn btn-primary" type="submit">${ico('check-circle')} Save company details</button></div></div></form></div><div class="card card-pad"><div class="card-titlebar"><div><h2 class="section-title">Data & security</h2><p class="subtext">Your records are stored in your own SQLite database</p></div></div><div class="settings-actions"><button class="action-tile" data-action="backup"><span class="action-ico">${ico('download')}</span><span><strong>Download full backup</strong><small>JSON export of customers, bookings, payments and expenses</small></span>${ico('chevron-right')}</button><button class="action-tile" data-action="restore"><span class="action-ico">${ico('upload')}</span><span><strong>Restore from backup</strong><small>Replace all records with a previously exported backup</small></span>${ico('chevron-right')}</button><button class="action-tile" data-action="export-bookings"><span class="action-ico">${ico('file-text')}</span><span><strong>Download booking register</strong><small>Excel-compatible CSV with outstanding balances</small></span>${ico('chevron-right')}</button><button class="action-tile" data-action="export-payments"><span class="action-ico">${ico('wallet')}</span><span><strong>Download payment register</strong><small>Excel-compatible CSV with payers and references</small></span>${ico('chevron-right')}</button></div><input id="restore-file" type="file" accept="application/json,.json" hidden/><div class="warning-box" style="margin-top:18px"><strong>Important:</strong> Download a backup regularly and keep it in a secure location. Restoring a backup replaces existing business records. Install a hosted HTTPS server for access outside your local network.</div></div></div><div class="card card-pad" style="margin-top:18px"><h2 class="section-title">About this application</h2><p class="inline-note" style="margin-top:12px">New Raja Transport runs in your PC browser or mobile browser. For shared records, all devices must connect to the same running server. An installable app shortcut is available in supported browsers over HTTPS or localhost. Financial figures use Indian rupees (INR).</p><p class="inline-note">Signed in as <strong>${esc(S.user.username)}</strong>. Click Sign out in the left menu to end your session.</p></div>`;}
function modal(title,subtitle,content,size=''){const root=el('modal-root');root.innerHTML=`<div class="modal ${size}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">${ico('x')}</button></div><div class="modal-body">${content}</div></div>`;root.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>root.querySelector('input:not([type=hidden]),select')?.focus(),40);}
function closeModal(){el('modal-root').hidden=true;el('modal-root').innerHTML='';document.body.style.overflow='';}
async function customersAll(){return api('/api/customers');}
async function bookingsAll(){return api('/api/bookings');}
async function bookingForm(existing=null){const customers=await customersAll();if(!customers.length){modal('Customer required','Create a customer before recording their freight bookings.',empty('users','Create a customer first','Add the company or billing party, then create a booking.',`<button class="btn btn-primary" data-action="new-customer">${ico('plus')} Add customer</button>`),'sm');return;}
 const b=existing||{},d=S.today,generated=`NRT-${d.replaceAll('-','')}-${String(Date.now()%100000).padStart(5,'0')}`,due=dateShift(d,Math.min(3650,Number(S.settings.default_due_days||15)));
 const fields=`${subTitle('Consignment details')}${field('LR / GR number','lr_no',b.lr_no||generated,{required:true})}${field('Booking date','booking_date',b.booking_date||d,{type:'date',required:true})}${field('Bill to customer','customer_id',b.customer_id||customers[0].id,{span:2,required:true,options:customers.map(c=>[c.id,c.name])})}${field('Sender / consignor','sender_name',b.sender_name||'',{required:true})}${field('Sender phone','sender_phone',b.sender_phone||'')}${field('Receiver / consignee','receiver_name',b.receiver_name||'',{required:true})}${field('Receiver phone','receiver_phone',b.receiver_phone||'')}${field('Origin city','from_city',b.from_city||'',{required:true})}${field('Destination city','to_city',b.to_city||'',{required:true})}${field('Goods description','description',b.description||'',{span:2,placeholder:'e.g. Furniture, parcel, machinery'})}${field('Packages','packages',b.packages??1,{type:'number',min:0})}${field('Weight (kg)','weight_kg',b.weight_kg??0,{type:'number',min:0,step:'0.01'})}${subTitle('Payment & trip information')}${field('Total freight (₹)','freight',b.freight??'',{type:'number',min:0,step:'0.01',required:true})}${field('Payment due date','due_date',b.due_date||due,{type:'date',required:true})}${field('Vehicle number','vehicle_no',b.vehicle_no||'',{placeholder:'MH-15-XX-1234'})}${field('Driver name','driver_name',b.driver_name||'')}${field('Delivery status','delivery_status',b.delivery_status||'Booked',{options:['Booked','In Transit','Delivered','Cancelled']})}${field('Delivery date (optional)','delivered_date',b.delivered_date||'',{type:'date'})}${field('Notes','notes',b.notes||'',{span:2,type:'textarea'})}`;
 modal(existing?'Edit transport booking':'New transport booking',existing?`Update LR ${b.lr_no}`:'Enter LR details, customer, freight and due date.',forms('booking-form',fields,existing?'Save changes':'Create booking',`<strong>Payment tracking:</strong> Once saved, open this booking to record advance, partial or full payments. Outstanding and overdue days update automatically.`),'lg');el('booking-form').dataset.id=b.id||'';}
async function customerForm(existing=null){const c=existing||{};modal(existing?'Edit customer':'Add customer',existing?'Update customer profile.':'Create a billing account for transport bookings.',forms('customer-form',`${field('Customer / business name','name',c.name||'',{required:true,span:2})}${field('Phone number','phone',c.phone||'')}${field('WhatsApp number','whatsapp',c.whatsapp||'',{hint:'Include country code, or enter 10-digit Indian mobile'})}${field('GSTIN (optional)','gstin',c.gstin||'')}${field('Address','address',c.address||'',{span:2,type:'textarea'})}`,existing?'Update customer':'Add customer'));el('customer-form').dataset.id=c.id||'';}
async function paymentForm(bookingId=null,existing=null){const book=await bookingsAll(),available=book.filter(b=>b.delivery_status!=='Cancelled'&&(b.balance>0|| (existing&&b.id===existing.booking_id)));if(!available.length){modal('No pending bookings','A payment must be linked to a booking.',empty('check-circle','No unpaid bookings','Create a freight booking first or use the booking register to view payments.',`<button class="btn btn-primary btn-sm" data-action="new-booking">New booking</button>`),'sm');return;}
 const initial=available.find(b=>b.id===Number(bookingId||existing?.booking_id))||available[0];const id=existing?.id||'';const options=available.map(b=>[b.id,`${b.lr_no} — ${b.customer_name} (${rupee(b.balance+(existing?.booking_id===b.id?existing.amount:0))} due)`]);
 const form=`${field('Booking / LR','booking_id',initial.id,{options,required:true,span:2})}${field('Payment amount (₹)','amount',existing?.amount??initial.balance,{required:true,type:'number',min:0.01,step:'0.01'})}${field('Payment date','payment_date',existing?.payment_date||S.today,{type:'date',required:true})}${field('Paid by (sender name)','payer_name',existing?.payer_name||initial.customer_name,{required:true})}${field('Payment mode','method',existing?.method||'UPI',{options:['UPI','Cash','Bank Transfer','Cheque','Other']})}${field('Transaction / UTR / cheque number','reference',existing?.reference||'',{span:2})}${field('Notes','notes',existing?.notes||'',{span:2,type:'textarea'})}`;
 modal(existing?'Edit payment':'Record received payment',`Link every collection to its LR. ${esc(initial.lr_no)} has ${rupee(initial.balance)} outstanding.`,forms('payment-form',form,existing?'Update payment':'Save payment',`<strong>Partial payments supported:</strong> You can record multiple payments for the same LR. The remaining amount will update automatically.`));const f=el('payment-form');f.dataset.id=id;f.dataset.bookingId=String(initial.id);const select=f.elements.booking_id;if(existing)select.disabled=true;else select.addEventListener('change',()=>{const b=available.find(x=>x.id===Number(select.value));if(b){f.elements.amount.value=b.balance;f.elements.payer_name.value=b.customer_name;}});}
async function expenseForm(existing=null){const x=existing||{};modal(existing?'Edit expense':'Record an expense','Keep an accurate record of transport operating costs.',forms('expense-form',`${field('Expense date','expense_date',x.expense_date||S.today,{type:'date',required:true})}${field('Category','category',x.category||'Fuel',{options:['Fuel','Toll / FASTag','Driver Advance','Salary','Vehicle Repair','Maintenance','Office','Loading / Unloading','Other']})}${field('Amount (₹)','amount',x.amount??'',{type:'number',step:'0.01',min:0.01,required:true})}${field('Payment method','payment_method',x.payment_method||'Cash',{options:['Cash','UPI','Bank Transfer','Cheque','Other']})}${field('Paid to','paid_to',x.paid_to||'')}${field('Vehicle number','vehicle_no',x.vehicle_no||'')}${field('Description / notes','notes',x.notes||'',{type:'textarea',span:2})}`,existing?'Save changes':'Add expense'));el('expense-form').dataset.id=x.id||'';}
function detailCell(label,value){return `<div><span class="detail-label">${esc(label)}</span><div class="detail-value">${esc(value||'—')}</div></div>`;}
async function bookingDetail(id){const b=await api(`/api/bookings/${id}`);const debt=b.balance>0?(b.due_date<S.today?`<span class="red">${diffDays(S.today,b.due_date)} days overdue</span>`:`Due ${shortDate(b.due_date)}`):'No outstanding amount';const totalPaid=b.payments.reduce((n,p)=>n+p.amount,0);
 const detail=`<div class="detail-metrics"><div class="detail-metric"><span class="detail-label">Total freight</span><strong>${rupee(b.freight)}</strong></div><div class="detail-metric"><span class="detail-label">Collected</span><strong class="green">${rupee(totalPaid)}</strong></div><div class="detail-metric"><span class="detail-label">Remaining</span><strong class="${b.balance?'red':'green'}">${rupee(b.balance)}</strong></div></div><p class="inline-note">${pbadge(b)} &nbsp; ${deliveryBadge(b.delivery_status)} &nbsp; ${debt}</p><div class="detail-action-row" style="margin-top:19px"><button class="btn btn-primary btn-sm" data-action="payment-for-booking" data-id="${b.id}" ${b.balance<=0?'disabled':''}>${ico('plus')} Record payment</button><button class="btn btn-outline btn-sm" data-action="print-booking" data-id="${b.id}">${ico('printer')} Print invoice / LR</button><button class="btn btn-outline btn-sm" data-action="remind-booking" data-id="${b.id}">${ico('message-circle')} WhatsApp reminder</button><button class="btn btn-outline btn-sm" data-action="edit-booking" data-id="${b.id}">${ico('edit')} Edit</button></div><div class="detail-section"><h3>Shipment and billing</h3><div class="detail-grid">${detailCell('Billing customer',b.customer_name)}${detailCell('LR / consignment no.',b.lr_no)}${detailCell('Booking date',shortDate(b.booking_date))}${detailCell('Sender',b.sender_name)}${detailCell('Sender phone',b.sender_phone)}${detailCell('Receiver',b.receiver_name)}${detailCell('Receiver phone',b.receiver_phone)}${detailCell('Route',`${b.from_city} → ${b.to_city}`)}${detailCell('Payment due',shortDate(b.due_date))}${detailCell('Goods',b.description)}${detailCell('Packages / weight',`${b.packages} packages · ${fmt(b.weight_kg)} kg`)}${detailCell('Vehicle / driver',`${b.vehicle_no||'—'} / ${b.driver_name||'—'}`)}${detailCell('Delivery date',b.delivered_date?shortDate(b.delivered_date):'—')}${detailCell('Notes',b.notes||'—')}</div></div><div class="detail-section"><h3>Payment history (${b.payments.length})</h3>${b.payments.length?`<div class="table-scroll"><table class="mini-payment-list"><thead><tr><th>Date</th><th>Paid by</th><th>Mode / reference</th><th>Amount</th></tr></thead><tbody>${b.payments.map(p=>`<tr><td>${shortDate(p.payment_date)}</td><td>${esc(p.payer_name)}</td><td>${esc(p.method)} <span class="muted">${esc(p.reference||'')}</span></td><td><strong class="green">${rupee(p.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('wallet','No payments received','Record a payment when your customer pays an advance or freight balance.')}</div><div class="detail-action-row" style="justify-content:flex-end;margin-top:15px"><button class="btn btn-danger btn-sm" data-action="delete-booking" data-id="${b.id}">${ico('trash')} Delete booking</button></div>`;
 modal(`LR ${b.lr_no}`,`${b.from_city} → ${b.to_city} · ${b.customer_name}`,detail,'lg');}
async function customerLedger(id){const cs=await customersAll(),c=cs.find(x=>x.id===Number(id));if(!c){toast('Customer not found','error');return;}const rows=await api(`/api/bookings?customer_id=${id}`);modal(`Customer ledger: ${c.name}`,`${rows.length} freight bookings · ${rupee(c.balance)} outstanding`,`<div class="detail-metrics"><div class="detail-metric"><span class="detail-label">Freight booked</span><strong>${rupee(c.total_freight)}</strong></div><div class="detail-metric"><span class="detail-label">Collected</span><strong class="green">${rupee(c.total_freight-c.balance)}</strong></div><div class="detail-metric"><span class="detail-label">Outstanding</span><strong class="${c.balance?'red':'green'}">${rupee(c.balance)}</strong></div></div><p class="inline-note">${esc(c.phone||'No phone')} · ${esc(c.gstin||'GSTIN not specified')} · ${esc(c.address||'')}</p><div class="detail-section"><h3>Booking-wise account statement</h3><div class="table-scroll"><table class="mini-payment-list"><thead><tr><th>LR</th><th>Date</th><th>Freight</th><th>Received</th><th>Balance</th><th></th></tr></thead><tbody>${rows.length?rows.map(b=>`<tr><td><strong>${esc(b.lr_no)}</strong></td><td>${shortDate(b.booking_date)}</td><td>${rupee(b.freight)}</td><td class="green">${rupee(b.paid)}</td><td class="${b.balance?'red':''}">${rupee(b.balance)}</td><td><button class="card-link" data-booking="${b.id}">Open</button></td></tr>`).join(''):'<tr><td colspan="6">No bookings for this customer</td></tr>'}</tbody></table></div></div>`,'lg');}
function download(url){const a=document.createElement('a');a.href=url;document.body.appendChild(a);a.click();a.remove();}
function whatsappBooking(id){api(`/api/bookings/${id}`).then(b=>{let phone=String(b.customer_whatsapp||b.customer_phone||'').replace(/\D/g,'');if(phone.length===10)phone='91'+phone;if(phone.length<11){toast('Add a valid WhatsApp number to the billed customer first.','error');return;}const msg=`Hello ${b.customer_name}, this is a payment reminder from ${S.settings.company_name||'New Raja Transport'}.\nLR: ${b.lr_no}\nRoute: ${b.from_city} to ${b.to_city}\nFreight: ${rupee(b.freight)}\nReceived: ${rupee(b.paid)}\nPending: ${rupee(b.balance)}\nDue date: ${shortDate(b.due_date)}${b.due_date<S.today?` (${diffDays(S.today,b.due_date)} days overdue)`:''}\nPlease arrange payment at your earliest convenience. Thank you.`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer');}).catch(e=>toast(e.message,'error'));}
function printHeader(type,number){const s=S.settings;return `<div class="print-company"><div><h1>${esc(s.company_name||'New Raja Transport')}</h1><p>${esc(s.tagline||'Transport & Logistics Management')}</p><p>${esc(s.address||'')}</p><p>${esc(s.phone||'')}</p>${s.gstin?`<p>GSTIN: ${esc(s.gstin)}</p>`:''}</div><div style="text-align:right"><h2>${esc(type)}</h2><p>${esc(number)}</p><p>Printed: ${shortDate(S.today)}</p></div></div>`;}
const printInfo=(name,value)=>`<div><div class="print-label">${esc(name)}</div><div class="print-value">${esc(value||'—')}</div></div>`;
async function printBooking(id){const b=await api(`/api/bookings/${id}`);el('print-area').innerHTML=`${printHeader('FREIGHT BOOKING / LR',b.lr_no)}<div class="print-grid">${printInfo('LR number',b.lr_no)}${printInfo('Date',shortDate(b.booking_date))}${printInfo('Bill to',b.customer_name)}${printInfo('Sender / Consignor',b.sender_name)}${printInfo('Receiver / Consignee',b.receiver_name)}${printInfo('From',b.from_city)}${printInfo('To',b.to_city)}${printInfo('Vehicle',b.vehicle_no)}${printInfo('Driver',b.driver_name)}${printInfo('Due date',shortDate(b.due_date))}</div><h2>Goods & freight details</h2><table><thead><tr><th>Description</th><th>Packages</th><th>Weight (kg)</th><th>Freight (INR)</th></tr></thead><tbody><tr><td>${esc(b.description||'Goods consignment')}</td><td>${b.packages}</td><td>${fmt(b.weight_kg)}</td><td>${rupee(b.freight)}</td></tr></tbody></table><div class="print-total">Total freight: ${rupee(b.freight)}<br/>Amount received: ${rupee(b.paid)}<br/>Balance due: ${rupee(b.balance)}</div><p>Delivery status: ${esc(b.delivery_status)}</p><p>Notes: ${esc(b.notes||'—')}</p><div class="print-footer"><span>Computer-generated booking record</span><span>Authorized signature __________________</span></div>`;window.print();}
async function printPayment(id){let p=S.payments.find(x=>x.id===Number(id));if(!p){const payments=await api('/api/payments');p=payments.find(x=>x.id===Number(id));}if(!p)throw new Error('Payment not found');const b=await api(`/api/bookings/${p.booking_id}`);el('print-area').innerHTML=`${printHeader('PAYMENT RECEIPT',`#${String(p.id).padStart(5,'0')}`)}<div class="print-grid">${printInfo('Receipt no.',`#${String(p.id).padStart(5,'0')}`)}${printInfo('Payment date',shortDate(p.payment_date))}${printInfo('LR / Consignment',p.lr_no||b.lr_no)}${printInfo('Billing customer',p.customer_name||b.customer_name)}${printInfo('Received from',p.payer_name)}${printInfo('Payment method',p.method)}${printInfo('Reference / UTR',p.reference)}${printInfo('Route',`${b.from_city} → ${b.to_city}`)}</div><h2>Payment details</h2><table><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody><tr><td>Freight collection for LR ${esc(b.lr_no)}</td><td>${rupee(p.amount)}</td></tr></tbody></table><div class="print-total">Amount received: ${rupee(p.amount)}<br/>Current LR balance: ${rupee(b.balance)}</div><p>${esc(p.notes||'')}</p><div class="print-footer"><span>Thank you for your payment.</span><span>Authorized signature __________________</span></div>`;window.print();}
const actionBusy=new Set();
async function handleForm(ev){const f=ev.target;if(!['booking-form','customer-form','payment-form','expense-form','settings-form'].includes(f.id))return;ev.preventDefault();if(actionBusy.has(f.id))return;actionBusy.add(f.id);const data=Object.fromEntries(new FormData(f));const id=f.dataset.id;const err=el('modal-error');if(err)err.hidden=true;try{let path,method,payload=data;
 if(f.id==='booking-form'){path='/api/bookings'+(id?'/'+id:'');method=id?'PATCH':'POST';}
 if(f.id==='customer-form'){path='/api/customers'+(id?'/'+id:'');method=id?'PATCH':'POST';}
 if(f.id==='payment-form'){if(id)data.booking_id=f.dataset.bookingId;path='/api/payments'+(id?'/'+id:'');method=id?'PATCH':'POST';}
 if(f.id==='expense-form'){path='/api/expenses'+(id?'/'+id:'');method=id?'PATCH':'POST';}
 if(f.id==='settings-form'){path='/api/settings';method='PUT';}
 const result=await api(path,{method,body:payload});if(f.id==='settings-form')S.settings=result;closeModal();toast(id?'Changes saved successfully':'Record saved successfully','success');await go(S.page);if(f.id==='booking-form'&&!id)await bookingDetail(result.id);
 }catch(e){if(err){err.textContent=e.message;err.hidden=false;}else toast(e.message,'error');}finally{actionBusy.delete(f.id);}}
async function handleAction(action,id){switch(action){
 case'close-modal':closeModal();break;
 case'reload':await go(S.page);break;
 case'new-booking':await bookingForm();break;
 case'edit-booking':await bookingForm(await api(`/api/bookings/${id}`));break;
 case'new-customer':await customerForm();break;
 case'edit-customer':await customerForm((await customersAll()).find(x=>x.id===Number(id)));break;
 case'new-payment':await paymentForm();break;
 case'payment-for-booking':await paymentForm(Number(id));break;
 case'edit-payment':{const row=(S.payments.length?S.payments:await api('/api/payments')).find(p=>p.id===Number(id));if(!row)throw new Error('Payment not found');await paymentForm(row.booking_id,row);break;}
 case'new-expense':await expenseForm();break;
 case'edit-expense':await expenseForm(S.expenses.find(e=>e.id===Number(id)));break;
 case'print-booking':await printBooking(id);break;
 case'print-payment':await printPayment(id);break;
 case'remind-booking':whatsappBooking(id);break;
 case'open-overdue':S.filters.bookings.payment='overdue';await go('bookings');break;
 case'delete-booking':if(confirm('Delete this LR booking? Only bookings without any payments can be deleted.')){await api(`/api/bookings/${id}`,{method:'DELETE'});closeModal();toast('Booking deleted','success');await go(S.page);}break;
 case'delete-customer':if(confirm('Delete this customer? Only customers without bookings can be deleted.')){await api(`/api/customers/${id}`,{method:'DELETE'});toast('Customer deleted','success');await go(S.page);}break;
 case'delete-payment':if(confirm('Delete this payment? This will increase the booking’s outstanding balance.')){await api(`/api/payments/${id}`,{method:'DELETE'});toast('Payment deleted','success');await go(S.page);}break;
 case'delete-expense':if(confirm('Delete this expense?')){await api(`/api/expenses/${id}`,{method:'DELETE'});toast('Expense deleted','success');await go(S.page);}break;
 case'export-bookings':download('/api/export/bookings');break;
 case'export-payments':download('/api/export/payments');break;
 case'export-expenses':download('/api/export/expenses');break;
 case'export-customers':download('/api/export/customers');break;
 case'backup':download('/api/backup');break;
 case'restore':el('restore-file')?.click();break;
 case'apply-report':{const from=el('report-from')?.value,to=el('report-to')?.value;if(!from||!to)throw new Error('Select both report dates');S.reportFilter={from,to};await go('reports');break;}
 case'demo':if(confirm('Create SAMPLE records for learning? All demo records are clearly named DEMO and should be removed before real use.')){await api('/api/demo',{method:'POST',body:{}});toast('Demo data created','success');await go('dashboard');}break;
 case'logout':await api('/api/logout',{method:'POST',body:{}});showAuth(false);break;
 }}
let filterTimer=null;
function bind(){el('auth-form').addEventListener('submit',signIn);document.addEventListener('submit',handleForm);document.addEventListener('click',async ev=>{
 const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();closeModal();await go(nav.dataset.nav);return;}
 const booking=ev.target.closest('[data-booking]');if(booking){ev.preventDefault();try{await bookingDetail(booking.dataset.booking);}catch(e){toast(e.message,'error');}return;}
 const customer=ev.target.closest('[data-customer]');if(customer){ev.preventDefault();try{await customerLedger(customer.dataset.customer);}catch(e){toast(e.message,'error');}return;}
 const action=ev.target.closest('[data-action]');if(action){ev.preventDefault();try{await handleAction(action.dataset.action,action.dataset.id);}catch(e){toast(e.message,'error');}return;}
 if(ev.target===el('modal-root'))closeModal();
 });
 document.addEventListener('input',ev=>{const control=ev.target.closest('[data-filter]');if(!control)return;const [page,key]=control.dataset.filter.split('.');S.filters[page][key]=control.value;clearTimeout(filterTimer);filterTimer=setTimeout(()=>go(page),360);});
 document.addEventListener('change',async ev=>{const control=ev.target.closest('select[data-filter]');if(control){const [page,key]=control.dataset.filter.split('.');S.filters[page][key]=control.value;clearTimeout(filterTimer);await go(page);return;}
 if(ev.target.id==='restore-file'){const file=ev.target.files[0];ev.target.value='';if(!file)return;if(file.size>1000000){toast('Backup exceeds 1 MB restore limit. Contact administrator for large restore.','error');return;}try{const obj=JSON.parse(await file.text());if(obj.app!=='New Raja Transport')throw new Error('This is not a New Raja Transport backup');if(!confirm('WARNING: Restoring will DELETE ALL current customers, bookings, payments and expenses and replace them with backup data. Do you want to continue?'))return;if(!confirm('Final confirmation: Have you downloaded a fresh backup of current data? Click OK to replace all records.'))return;await api('/api/restore',{method:'POST',body:{...obj,confirm_replace:true}});toast('Backup restored successfully','success');await go('dashboard');}catch(e){toast(e.message,'error');}return;}
 });
 el('menu-toggle').addEventListener('click',()=>{el('sidebar').classList.toggle('open');el('mobile-backdrop').classList.toggle('active');});el('mobile-backdrop').addEventListener('click',mobileClose);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!el('modal-root').hidden)closeModal();});
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();S.installEvent=e;el('install-app').hidden=false;});
 el('install-app').addEventListener('click',async()=>{if(S.installEvent){S.installEvent.prompt();await S.installEvent.userChoice;S.installEvent=null;el('install-app').hidden=true;}});
 window.addEventListener('appinstalled',()=>{el('install-app').hidden=true;toast('New Raja Transport installed','success');});
}
bind();startup();
if('serviceWorker'in navigator&& (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('/sw.js').catch(()=>{});
})();
